  ('q_0255', 'islamic', 'quran', 'text', 'في أي سورة وردت هذه الآية الكريمة؟', 'سورة لقمان', null, null, '{"quote": "مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَٰحِدَةٍ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ"}', 6, 3, null, null, 'Quran Core Dataset (mjmirza) — CC BY 4.0', 'لقمان: 28', true, true, '["قرآن", "آيات"]', 'quran-dataset', 'surah_of:31:28'),
  ('q_0256', 'islamic', 'quran', 'text', 'في أي سورة وردت هذه الآية الكريمة؟', 'سورة ص', null, null, '{"quote": "إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ"}', 6, 3, null, null, 'Quran Core Dataset (mjmirza) — CC BY 4.0', 'ص: 23', true, true, '["قرآن", "آيات"]', 'quran-dataset', 'surah_of:38:23'),
  ('q_0257', 'islamic', 'quran', 'text', 'في أي سورة وردت هذه الآية الكريمة؟', 'سورة التوبة', null, null, '{"quote": "وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ"}', 6, 3, null, null, 'Quran Core Dataset (mjmirza) — CC BY 4.0', 'التوبة: 98', true, true, '["قرآن", "آيات"]', 'quran-dataset', 'surah_of:9:98'),
